+            // Verify does an exact image compare, so freeze the blinking cursor.
+            await Page.AddStyleTagAsync(new PageAddStyleTagOptions
+            {
+                Content = ".xterm-cursor-layer, .xterm-cursor { visibility: hidden !important; }"
+            });
