+        // --- Helpers --------------------------------------------------------
+
+        /// <summary>Recursively empties a remote directory so scenarios start clean.</summary>
+        private async Task CleanDirectoryAsync(string directory)
+        {
+            var items = await Service.ListDirectoryAsync(directory);
